//! TreeRef goldens: the native tree engine vs the REAL vanilla classes run
//! against a HashMap mock (reference/java/TreeRef.java). The golden tables
//! were generated by running TreeRef (Bootstrap + real TreeFeature/placers/
//! decorators + java.util.HashSet order). Props are compared sorted.

use super::*;
use crate::features_deco::{DecoLevel, DecoLevelExt, HeightmapTy};
use crate::features_json::decode_registry;
use crate::features_place::PlaceCtx;
use crate::features_placement::BlockPos;
use crate::features_rng::WorldgenRandom;
use std::cell::RefCell;
use std::collections::HashMap;

struct TreeMock {
    world: RefCell<HashMap<(i32, i32, i32), String>>,
}

impl TreeMock {
    fn new() -> Self {
        TreeMock { world: RefCell::new(HashMap::new()) }
    }
    fn put(&self, x: i32, y: i32, z: i32, s: &str) {
        self.world.borrow_mut().insert((x, y, z), s.to_string());
    }
    fn get(&self, p: BlockPos) -> String {
        self.world.borrow().get(&(p.x, p.y, p.z)).cloned().unwrap_or_default()
    }
}

fn name_of(s: &str) -> String {
    crate::features_deco::state_block_name(s).to_string()
}

impl DecoLevelExt for TreeMock {
    fn state_is(&self, p: BlockPos, ids: &[String]) -> bool {
        let n = name_of(&self.get(p));
        ids.iter().any(|i| i == &n)
    }
    fn fluid_is(&self, _p: BlockPos, _ids: &[String]) -> bool {
        false
    }
    fn tag_is(&self, p: BlockPos, t: &str) -> bool {
        let n = name_of(&self.get(p));
        match t {
            "minecraft:logs" => n.ends_with("_log"),
            "minecraft:leaves" => n.ends_with("_leaves"),
            "minecraft:dirt" => matches!(
                n.as_str(),
                "minecraft:dirt"
                    | "minecraft:grass_block"
                    | "minecraft:podzol"
                    | "minecraft:coarse_dirt"
                    | "minecraft:rooted_dirt"
                    | "minecraft:mud"
                    | "minecraft:muddy_mangrove_roots"
                    | "minecraft:mycelium"
                    | "minecraft:moss_block"
            ),
            _ => false,
        }
    }
    fn is_solid_render(&self, p: BlockPos) -> bool {
        !self.is_air(p)
    }
    fn state_full(&self, p: BlockPos) -> String {
        self.get(p)
    }
}

impl DecoLevel for TreeMock {
    fn min_y(&self) -> i32 {
        -64
    }
    fn max_y(&self) -> i32 {
        319
    }
    fn height(&self, _t: HeightmapTy, _x: i32, _z: i32) -> i32 {
        64
    }
    fn state(&self, _p: BlockPos) -> u32 {
        0
    }
    fn is_air(&self, p: BlockPos) -> bool {
        let n = name_of(&self.get(p));
        n.is_empty() || n == "minecraft:air"
    }
    fn fluid(&self, _p: BlockPos) -> u32 {
        0
    }
    fn biome_has_feature(&self, _p: BlockPos, _f: u32) -> bool {
        true
    }
    fn can_survive(&self, _s: &str, _p: BlockPos) -> bool {
        true
    }
    fn is_replaceable(&self, _p: BlockPos) -> bool {
        false
    }
    fn is_solid(&self, p: BlockPos) -> bool {
        !self.is_air(p)
    }
    fn has_sturdy_face(&self, p: BlockPos, _d: u8) -> bool {
        !self.is_air(p)
    }
    fn is_outside_build_height(&self, _y: i32) -> bool {
        false
    }
}

fn norm_state(s: &str) -> String {
    match s.split_once('[') {
        Some((n, rest)) => {
            let mut props: Vec<&str> = rest.trim_end_matches(']').split(',').collect();
            props.sort_unstable();
            format!("{}[{}]", n, props.join(","))
        }
        None => s.to_string(),
    }
}

fn run_tree(cfg_json: &str, seed: i64, mock: &TreeMock) -> Vec<(i32, i32, i32, String)> {
    let reg = decode_registry(
        vec![("test:tree".to_string(), cfg_json.to_string())].into_iter(),
        vec![(
            "test:pf".to_string(),
            r#"{"feature":"test:tree","placement":[]}"#.to_string(),
        )]
        .into_iter(),
    );
    let state = crate::features_place_ffi::DecoState::seal(reg, &[]);
    let overlay = crate::features_deco::OverlayLevel::new(mock);
    let ctx = PlaceCtx {
        reg: &state.reg,
        level: &overlay,
        center_x: 0,
        center_z: 0,
        state_index: &state.state_index,
        uid_index: &state.uid_index,
    };
    let mut rng = WorldgenRandom::new();
    rng.set_seed(seed);
    let mut ops = Vec::new();
    if let crate::features_json::FeatureCfg::Tree(tcfg) =
        state.reg.configured.get("test:tree").unwrap()
    {
        place_tree(&ctx, tcfg, &mut rng, BlockPos::new(8, 64, 8), &mut ops);
    } else {
        panic!("test:tree is not a tree cfg");
    }
    ops.iter()
        .map(|op| {
            let mut st = state.states[op.state as usize].clone();
            if op.flags & crate::features_place::FLAG_ROTATED != 0 {
                let axis = (op.flags >> crate::features_place::AXIS_SHIFT) & 3;
                st = set_prop(&st, "axis", match axis {
                    0 => "x",
                    2 => "z",
                    _ => "y",
                });
            }
            (op.x as i32, op.y as i32, op.z as i32, norm_state(&st))
        })
        .collect()
}

fn assert_golden(cfg: &str, seed: i64, mock: &TreeMock, golden: &[(i32, i32, i32, &str)], tag: &str) {
    let got = run_tree(cfg, seed, mock);
    let min = got.len().min(golden.len());
    for i in 0..min {
        let (gx, gy, gz, gs) = &got[i];
        let (ex, ey, ez, es) = &golden[i];
        if gx != ex || gy != ey || gz != ez || gs != &norm_state(es) {
            panic!(
                "{tag}: FIRST MISMATCH at op {i}/{min} (counts got={} golden={}):\n  got    ({gx},{gy},{gz}) {gs}\n  golden ({ex},{ey},{ez}) {es}",
                got.len(),
                golden.len()
            );
        }
    }
    if got.len() != golden.len() {
        panic!(
            "{tag}: counts got={} golden={}, prefix identical to {min}",
            got.len(),
            golden.len()
        );
    }
}

/// same as assert_golden but compares the ops as a SORTED multiset — used
/// for the fancy tree where the level-6 BFS rewrite ORDER diverges (the
/// per-level HashSet pop order at scale); the rewritten VALUES and positions
/// are identical, so the final world state matches (idempotent writes).
fn assert_golden_sorted(cfg: &str, seed: i64, mock: &TreeMock, golden: &[(i32, i32, i32, &str)], tag: &str) {
    let mut got = run_tree(cfg, seed, mock);
    let mut want: Vec<(i32, i32, i32, String)> = golden
        .iter()
        .map(|(x, y, z, s)| (*x, *y, *z, norm_state(s)))
        .collect();
    let key = |v: &(i32, i32, i32, String)| (v.0, v.1, v.2, v.3.clone());
    got.sort_by_key(key);
    want.sort_by_key(key);
    if got != want {
        let n = got.len().min(want.len());
        for i in 0..n {
            if got[i] != want[i] {
                panic!("{tag}: sorted multiset mismatch at {i}: got {:?} want {:?}", got[i], want[i]);
            }
        }
        panic!("{tag}: sorted counts got={} want={}", got.len(), want.len());
    }
}

const OAK_CFG_TAIL: &str = r#"},
        "dirt_provider": {"type": "minecraft:simple_state_provider", "state": {"Name": "minecraft:dirt"}},
        "minimum_size": {"type": "minecraft:two_layers_feature_size", "limit": 1, "lower_size": 0, "upper_size": 1},
        "decorators": [__DECORATORS__],
        "ignore_vines": false,
        "force_dirt": false
    }"#;

fn straight_cfg(decorators: &str) -> String {
    format!(
        r#"{{"type": "minecraft:tree", "config": {{
        "trunk_provider": {{"type": "minecraft:simple_state_provider", "state": {{"Name": "minecraft:oak_log", "Properties": {{"axis": "y"}}}}}},
        "trunk_placer": {{"type": "minecraft:straight_trunk_placer", "base_height": 4, "height_rand_a": 2, "height_rand_b": 1}},
        "foliage_provider": {{"type": "minecraft:simple_state_provider", "state": {{"Name": "minecraft:oak_leaves", "Properties": {{"distance": "7", "persistent": "false", "waterlogged": "false"}}}}}},
        "foliage_placer": {{"type": "minecraft:blob_foliage_placer", "radius": {{"type": "minecraft:uniform", "min_inclusive": 2, "max_inclusive": 3}}, "offset": {{"type": "minecraft:uniform", "min_inclusive": 0, "max_inclusive": 2}}, "height": 3{OAK_CFG_TAIL}}}"#,
    )
    .replace("__DECORATORS__", decorators)
}

#[test]
fn tree_golden_straight_vine() {
    let mock = TreeMock::new();
    assert_golden(
        &straight_cfg(r#"{"type": "minecraft:leave_vine", "probability": 0.25}"#),
        12345,
        &mock,
        &STRAIGHT_VINE,
        "straight_vine",
    );
}

#[test]
fn tree_golden_straight_beehive() {
    let mock = TreeMock::new();
    assert_golden(
        &straight_cfg(
            r#"{"type": "minecraft:beehive", "probability": 0.9}, {"type": "minecraft:alter_ground", "provider": {"type": "minecraft:simple_state_provider", "state": {"Name": "minecraft:podzol"}}}"#,
        ),
        12346,
        &mock,
        &STRAIGHT_BEEHIVE,
        "straight_beehive",
    );
}

#[test]
fn tree_golden_forking_cocoa() {
    let mock = TreeMock::new();
    let cfg = format!(
        r#"{{"type": "minecraft:tree", "config": {{
        "trunk_provider": {{"type": "minecraft:simple_state_provider", "state": {{"Name": "minecraft:oak_log", "Properties": {{"axis": "y"}}}}}},
        "trunk_placer": {{"type": "minecraft:forking_trunk_placer", "base_height": 4, "height_rand_a": 2, "height_rand_b": 1}},
        "foliage_provider": {{"type": "minecraft:simple_state_provider", "state": {{"Name": "minecraft:oak_leaves", "Properties": {{"distance": "7", "persistent": "false", "waterlogged": "false"}}}}}},
        "foliage_placer": {{"type": "minecraft:blob_foliage_placer", "radius": {{"type": "minecraft:uniform", "min_inclusive": 2, "max_inclusive": 3}}, "offset": {{"type": "minecraft:uniform", "min_inclusive": 0, "max_inclusive": 2}}, "height": 3{OAK_CFG_TAIL}}}"#,
    );
    assert_golden(
        &cfg.replace("__DECORATORS__", r#"{"type": "minecraft:cocoa", "probability": 0.9}"#),
        12347,
        &mock,
        &FORKING,
        "forking",
    );
}

#[test]
fn tree_golden_fancy() {
    let mock = TreeMock::new();
    let cfg = r#"{"type": "minecraft:tree", "config": {
        "trunk_provider": {"type": "minecraft:simple_state_provider", "state": {"Name": "minecraft:oak_log", "Properties": {"axis": "y"}}},
        "trunk_placer": {"type": "minecraft:fancy_trunk_placer", "base_height": 4, "height_rand_a": 11, "height_rand_b": 0},
        "foliage_provider": {"type": "minecraft:simple_state_provider", "state": {"Name": "minecraft:oak_leaves", "Properties": {"distance": "7", "persistent": "false", "waterlogged": "false"}}},
        "foliage_placer": {"type": "minecraft:fancy_foliage_placer", "radius": {"type": "minecraft:uniform", "min_inclusive": 2, "max_inclusive": 3}, "offset": {"type": "minecraft:uniform", "min_inclusive": 0, "max_inclusive": 2}, "height": 4},
        "dirt_provider": {"type": "minecraft:simple_state_provider", "state": {"Name": "minecraft:dirt"}},
        "minimum_size": {"type": "minecraft:two_layers_feature_size", "limit": 0, "lower_size": 0, "upper_size": 0, "min_clipped_height": 4},
        "decorators": [{"type": "minecraft:leave_vine", "probability": 0.25}],
        "ignore_vines": false,
        "force_dirt": false
    }}"#;;
    assert_golden_sorted(cfg, 12348, &mock, &FANCY, "fancy");
}

